// ---------------------------------------------------------------------------
// Poses, as animation clips.
//
// A rotation track replaces a node's rotation outright, so every euler below
// is absolute and includes the rest pose's own components — the brows, for
// instance, are splayed 20 degrees around Y to sit on the curve of the face,
// and every brow keyframe has to carry that or they would snap flat.
// ---------------------------------------------------------------------------
const DEG = Math.PI / 180;

/** three.js's default XYZ Euler order, so the clips read the same in-engine. */
function quat([rx, ry, rz]) {
  const [x, y, z] = [rx * DEG * 0.5, ry * DEG * 0.5, rz * DEG * 0.5];
  const [c1, c2, c3] = [Math.cos(x), Math.cos(y), Math.cos(z)];
  const [s1, s2, s3] = [Math.sin(x), Math.sin(y), Math.sin(z)];
  return [
    s1 * c2 * c3 + c1 * s2 * s3,
    c1 * s2 * c3 - s1 * c2 * s3,
    c1 * c2 * s3 + s1 * s2 * c3,
    c1 * c2 * c3 - s1 * s2 * s3,
  ];
}

const move = (node, times, values) => ({ node, path: 'translation', times, values });
const size = (node, times, values) => ({ node, path: 'scale', times, values });
const turn = (node, times, eulers) => ({ node, path: 'rotation', times, values: eulers.map(quat) });

/** The same scale track on both eyes — they never do different things. */
const eyes = (times, values) => [size('eyeL', times, values), size('eyeR', times, values)];
/** Brows mirror: an angle that lifts one inner end lifts the other. */
const brows = (times, values) => [
  turn('browL', times, values.map((z) => [0, -20, z])),
  turn('browR', times, values.map((z) => [0, 20, -z])),
];
/**
 * Symmetric limb pairs, given as [pitch, splay]. Splay is mirrored because a
 * left arm reaching outward and a right arm reaching outward are opposite
 * signs about Z; pitch is not, because forward is forward for both.
 */
const pair = (left, right) => (times, values) => [
  turn(left, times, values.map(([x, z]) => [x, 0, -z])),
  turn(right, times, values.map(([x, z]) => [x, 0, z])),
];
const arms = pair('upperArmL', 'upperArmR');
const foreArms = pair('foreArmL', 'foreArmR');
const thighs = pair('thighL', 'thighR');
const shins = pair('shinL', 'shinR');

